const express = require('express');

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const app = express();

app.get('/chunked', async (req, res) => {
  res.write('Hello');
  await sleep(1000);
  res.write('World');
  await sleep(1000);
  res.write('Bye');
  res.end();
})

app.listen(3000, () => {
  console.log('Server is running on port 3000');
})
